-- Run once (seed_runs). Odisha 2024 top-4 candidates' photos from the ECI results site, hosted in our Blob store,
-- generated by scraper/src/bihar/photos-cli.ts. Fill-only: a photo already set (leaders, admin uploads) is kept.
-- The image credits above the guard are idempotent and run every time.
SELECT NOT EXISTS (SELECT 1 FROM seed_runs WHERE name = 'seed_od_candidate_photos')
   AS seed_apply \gset
\if :seed_apply

